-- create the project table gsid sequence
CREATE SEQUENCE
  gs.seq_project_gsid
AS
  integer
OWNED BY
  gs.project.id;

-- offset the next id to be generated by a margin from migrated project gsids
SELECT
  setval(
	'gs.seq_project_gsid',
	(
		WITH project_numeric_gsids(gsid_number) AS (
		SELECT
			cast(unnest(regexp_matches("GSID", '^GS(\d+)$')) AS integer)
		FROM
			staging."Projects"
		)
		SELECT
		10000 + max(gsid_number)
		FROM
		project_numeric_gsids
		WHERE
		gsid_number IS NOT NULL
	)
  );

  -- default gsid to 'GS'-prefixed next value of the sequence
  ALTER TABLE gs.project
  ALTER COLUMN gsid SET DEFAULT ('GS' || nextval('gs.seq_project_gsid'));


